js:
var scroller = root.querySelector('.scr-fade-up-feed-scroll');
var items = Array.prototype.slice.call(root.querySelectorAll('.scr-fade-up-feed-item'));
var num = root.querySelector('.scr-fade-up-feed-num');
var fill = root.querySelector('.scr-fade-up-feed-fill');
if (!scroller || !items.length) return;
var pending = items.slice();
var seen = 0;
var io = new IntersectionObserver(function (entries) {
  var batch = entries.filter(function (e) { return e.isIntersecting; });
  batch.sort(function (a, b) { return items.indexOf(a.target) - items.indexOf(b.target); });
  batch.forEach(function (e, i) { reveal(e.target, i * 90); });
}, { root: scroller, rootMargin: '0px 0px -10% 0px', threshold: 0.3 });
function reveal(el, delay) {
  var at = pending.indexOf(el);
  if (at < 0) return;
  pending.splice(at, 1);
  el.style.transitionDelay = delay + 'ms';
  el.classList.add('scr-fade-up-feed-in');
  io.unobserve(el);
  seen++;
  if (num) num.textContent = String(seen);
}
items.forEach(function (el) { io.observe(el); });
function onScroll() {
  if (fill) {
    var max = scroller.scrollHeight - scroller.clientHeight;
    fill.style.width = (max > 0 ? (scroller.scrollTop / max) * 100 : 100) + '%';
  }
  var top = scroller.getBoundingClientRect().top;
  pending.slice().forEach(function (el) {
    if (el.getBoundingClientRect().bottom < top) reveal(el, 0);
  });
}
scroller.addEventListener('scroll', onScroll, { passive: true });
onScroll();

