var scroller = root.querySelector('.scr-clip-wipe-deck-scroll');
var panels = Array.prototype.slice.call(root.querySelectorAll('.scr-clip-wipe-deck-panel'));
var replay = root.querySelector('.scr-clip-wipe-deck-replay');
if (!scroller || !panels.length) return;
var pending = panels.slice();
var io = new IntersectionObserver(function (entries) {
  var batch = entries.filter(function (e) { return e.isIntersecting; });
  batch.sort(function (a, b) { return panels.indexOf(a.target) - panels.indexOf(b.target); });
  batch.forEach(function (e, i) { wipe(e.target, i * 130); });
}, { root: scroller, rootMargin: '0px 0px -18% 0px', threshold: 0 });
function wipe(el, delay) {
  var at = pending.indexOf(el);
  if (at < 0) return;
  pending.splice(at, 1);
  var body = el.querySelector('.scr-clip-wipe-deck-body');
  el.style.transitionDelay = delay + 'ms';
  if (body) body.style.transitionDelay = (delay + 160) + 'ms, ' + (delay + 160) + 'ms';
  el.classList.add('scr-clip-wipe-deck-on');
  io.unobserve(el);
}
panels.forEach(function (el) { io.observe(el); });
function onScroll() {
  var top = scroller.getBoundingClientRect().top;
  pending.slice().forEach(function (el) {
    if (el.getBoundingClientRect().bottom < top) wipe(el, 0);
  });
}
scroller.addEventListener('scroll', onScroll, { passive: true });
if (replay) {
  replay.addEventListener('click', function () {
    scroller.scrollTop = 0;
    pending = panels.slice();
    panels.forEach(function (el) {
      el.classList.remove('scr-clip-wipe-deck-on');
      el.style.transitionDelay = '0ms';
      var body = el.querySelector('.scr-clip-wipe-deck-body');
      if (body) body.style.transitionDelay = '';
      void el.offsetWidth;
      io.observe(el);
    });
  });
}

