var scroller = root.querySelector('.scr-blur-focus-roll-scroll');
var cards = Array.prototype.slice.call(root.querySelectorAll('.scr-blur-focus-roll-card'));
var label = root.querySelector('.scr-blur-focus-roll-focus');
if (!scroller || !cards.length) return;
var queued = false;
function paint() {
  if (!root.isConnected) return;
  queued = false;
  var box = scroller.getBoundingClientRect();
  if (!box.height) return;
  var mid = box.top + box.height / 2;
  var best = null, bestD = Infinity;
  cards.forEach(function (card) {
    var r = card.getBoundingClientRect();
    var d = Math.abs((r.top + r.height / 2) - mid);
    var n = Math.min(1, d / (box.height / 2 + r.height / 2));
    card.style.filter = 'blur(' + (n * n * 7).toFixed(2) + 'px)';
    card.style.opacity = (1 - n * 0.72).toFixed(3);
    card.style.transform = 'scale(' + (1 - n * 0.13).toFixed(3) + ')';
    if (d < bestD) { bestD = d; best = card; }
  });
  cards.forEach(function (c) {
    c.classList.toggle('scr-blur-focus-roll-lead', c === best);
  });
  if (best && label) label.textContent = best.getAttribute('data-name') || '';
}
function schedule() { if (!queued) { queued = true; requestAnimationFrame(paint); } }
scroller.addEventListener('scroll', schedule, { passive: true });
paint();

