var scroller = root.querySelector('.scr-split-word-essay-scroll');
var blocks = Array.prototype.slice.call(root.querySelectorAll('.scr-split-word-essay-split'));
if (!scroller || !blocks.length) return;
blocks.forEach(function (block) {
  var words = block.textContent.trim().split(/\s+/);
  block.textContent = '';
  words.forEach(function (w, i) {
    var mask = document.createElement('span');
    mask.className = 'scr-split-word-essay-word';
    var inner = document.createElement('span');
    inner.className = 'scr-split-word-essay-inner';
    inner.textContent = w;
    inner.style.transitionDelay = (i * 55) + 'ms';
    mask.appendChild(inner);
    block.appendChild(mask);
    block.appendChild(document.createTextNode(' '));
  });
});
var io = new IntersectionObserver(function (entries) {
  entries.forEach(function (e) {
    if (!e.isIntersecting) return;
    e.target.classList.add('scr-split-word-essay-lit');
    io.unobserve(e.target);
  });
}, { root: scroller, rootMargin: '0px 0px -14% 0px', threshold: 0.2 });
blocks.forEach(function (b) { io.observe(b); });

