var rows = Array.prototype.slice.call(root.querySelectorAll('.scr-cascade-ledger-row'));
var fill = root.querySelector('.scr-cascade-ledger-spine-fill');
if (!scroller || !rows.length) return;
var pending = rows.slice();
var io = new IntersectionObserver(function (entries) {
  var batch = entries.filter(function (e) { return e.isIntersecting; });
  batch.sort(function (a, b) { return rows.indexOf(a.target) - rows.indexOf(b.target); });
  batch.forEach(function (e, i) { unfold(e.target, i * 80); });
}, { root: scroller, rootMargin: '0px 0px -6% 0px', threshold: 0.4 });
function unfold(el, delay) {
  var at = pending.indexOf(el);
  if (at < 0) return;
  pending.splice(at, 1);
  var node = el.querySelector('.scr-cascade-ledger-node');
  el.style.transitionDelay = delay + 'ms';
  if (node) node.style.transitionDelay = (delay + 180) + 'ms';
  el.classList.add('scr-cascade-ledger-open');
  io.unobserve(el);
}
rows.forEach(function (el) { io.observe(el); });
function onScroll() {
  if (fill) {
    var max = scroller.scrollHeight - scroller.clientHeight;
    var seen = max > 0 ? scroller.scrollTop / max : 1;
    var view = scroller.clientHeight / Math.max(1, scroller.scrollHeight);
    fill.style.height = Math.min(100, (view + seen * (1 - view)) * 100) + '%';
  }
  var top = scroller.getBoundingClientRect().top;
  pending.slice().forEach(function (el) {
    if (el.getBoundingClientRect().bottom < top) unfold(el, 0);
  });
