var track = root.querySelector('.scr-rotate-rack-track');
var cards = Array.prototype.slice.call(root.querySelectorAll('.scr-rotate-rack-card'));
var prev = root.querySelector('.scr-rotate-rack-prev');
var next = root.querySelector('.scr-rotate-rack-next');
if (!track || !cards.length) return;
var queued = false;
function paint() {
  if (!root.isConnected) return;
  queued = false;
  var box = track.getBoundingClientRect();
  if (!box.width) return;
  var mid = box.left + box.width / 2;
  cards.forEach(function (card) {
    var r = card.getBoundingClientRect();
    var n = ((r.left + r.width / 2) - mid) / (box.width / 2);
    n = Math.max(-1.3, Math.min(1.3, n));
    var a = Math.abs(n);
    card.style.transform = 'perspective(620px) rotateY(' + (-n * 36).toFixed(2) + 'deg) scale(' + (1 - a * 0.14).toFixed(3) + ')';
    card.style.opacity = (1 - a * 0.5).toFixed(3);
    card.classList.toggle('scr-rotate-rack-front', a < 0.22);
  });
  var max = track.scrollWidth - track.clientWidth;
  if (prev) prev.disabled = track.scrollLeft <= 2;
  if (next) next.disabled = track.scrollLeft >= max - 2;
}
function schedule() { if (!queued) { queued = true; requestAnimationFrame(paint); } }
function step(dir) {
  track.scrollBy({ left: dir * 130, behavior: 'smooth' });
}
track.addEventListener('scroll', schedule, { passive: true });
if (prev) prev.addEventListener('click', function () { step(-1); });
if (next) next.addEventListener('click', function () { step(1); });
paint();

