var native = typeof CSS !== 'undefined' && CSS.supports && CSS.supports('animation-timeline', 'scroll()');
var io = new IntersectionObserver(function (entries) {
  var batch = entries.filter(function (e) { return e.isIntersecting; });
  batch.sort(function (a, b) { return steps.indexOf(a.target) - steps.indexOf(b.target); });
  batch.forEach(function (e, i) { pop(e.target, i * 100); });
}, { root: scroller, rootMargin: '0px 0px -10% 0px', threshold: 0.35 });
function pop(el, delay) {
  var at = pending.indexOf(el);
  if (at < 0) return;
  pending.splice(at, 1);
  var card = el.querySelector('.scr-scale-timeline-card');
  var dot = el.querySelector('.scr-scale-timeline-dot');
