var sc = root.querySelector('.scr-lift-scorecard-sc');
var items = Array.prototype.slice.call(root.querySelectorAll('.scr-lift-scorecard-tile, .scr-lift-scorecard-grp, .scr-lift-scorecard-end'));

function show(el, d){
  el.style.setProperty('--scr-lift-scorecard-rd', d + 'ms');
  el.classList.add('scr-lift-scorecard-in');
}

if (!('IntersectionObserver' in window)) {
  items.forEach(function (el) { show(el, 0); });
} else {
  var io = new IntersectionObserver(function (entries) {
    var batch = entries.filter(function (e) { return e.isIntersecting; });
    batch.sort(function (a, b) { return a.target.offsetTop - b.target.offsetTop; });
    batch.forEach(function (e, i) {
      var idx = items.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        if (!items[k].classList.contains('scr-lift-scorecard-in')) {
          show(items[k], 0);
          io.unobserve(items[k]);
        }
      }
      show(e.target, i * 85);
      io.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.25, rootMargin: '0px 0px -6% 0px' });
  items.forEach(function (el) { io.observe(el); });
}

var pending = false;
function progress(){
  var span = sc.scrollHeight - sc.clientHeight;
  root.style.setProperty('--scr-lift-scorecard-p', span > 0 ? (sc.scrollTop / span).toFixed(4) : '1');
}
sc.addEventListener('scroll', function () {
  if (pending) return;
  pending = true;
  requestAnimationFrame(function () {
    if (!root.isConnected) return;
    pending = false;
    progress();
  });
}, { passive: true });
progress();

root.addEventListener('click', function (e) {
  var t = e.target && e.target.closest ? e.target.closest('.scr-lift-scorecard-tile') : null;
  if (!t || !root.contains(t)) return;
  t.setAttribute('aria-pressed', t.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
});

