var sc = root.querySelector('.scr-defog-glossary-sc');
var ents = Array.prototype.slice.call(root.querySelectorAll('.scr-defog-glossary-ent'));
var ixEl = root.querySelector('.scr-defog-glossary-ix');

function show(el, d){
  el.style.transitionDelay = d + 'ms';
  el.classList.add('scr-defog-glossary-in');
}

if (!('IntersectionObserver' in window)) {
  ents.forEach(function (el) { show(el, 0); });
} else {
  var reveal = new IntersectionObserver(function (entries) {
    var batch = entries.filter(function (e) { return e.isIntersecting; });
    batch.sort(function (a, b) { return a.target.offsetTop - b.target.offsetTop; });
    batch.forEach(function (e, i) {
      var idx = ents.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        if (!ents[k].classList.contains('scr-defog-glossary-in')) {
          show(ents[k], 0);
          reveal.unobserve(ents[k]);
        }
      }
      show(e.target, i * 95);
      reveal.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.3 });
  ents.forEach(function (el) { reveal.observe(el); });

  var track = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (e.isIntersecting) ixEl.textContent = e.target.getAttribute('data-ix');
    });
  }, { root: sc, rootMargin: '-42px 0px -62% 0px', threshold: 0 });
  ents.forEach(function (el) { track.observe(el); });
}

ents.forEach(function (el) {
  var btn = el.querySelector('.scr-defog-glossary-term');
  btn.addEventListener('click', function () {
    var open = el.classList.toggle('scr-defog-glossary-open');
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
});

