js:
var sc = root.querySelector('.scr-letter-manifesto-sc');
var blocks = Array.prototype.slice.call(root.querySelectorAll('.scr-letter-manifesto-blk'));

blocks.forEach(function (blk) {
  var hl = blk.querySelector('.scr-letter-manifesto-hl');
  var text = hl.textContent;
  hl.textContent = '';
  var frag = hl.ownerDocument.createDocumentFragment();
  for (var i = 0; i < text.length; i++) {
    if (text.charAt(i) === ' ') {
      frag.appendChild(hl.ownerDocument.createTextNode(' '));
      continue;
    }
    var span = hl.ownerDocument.createElement('span');
    span.className = 'scr-letter-manifesto-ch';
    span.style.setProperty('--scr-letter-manifesto-d', String(i));
    var glyph = hl.ownerDocument.createElement('i');
    glyph.textContent = text.charAt(i);
    span.appendChild(glyph);
    frag.appendChild(span);
  }
  hl.appendChild(frag);
});

if (!('IntersectionObserver' in window)) {
  blocks.forEach(function (b) { b.classList.add('scr-letter-manifesto-in'); });
} else {
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (!e.isIntersecting) return;
      var idx = blocks.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        blocks[k].classList.add('scr-letter-manifesto-in');
        io.unobserve(blocks[k]);
      }
      e.target.classList.add('scr-letter-manifesto-in');
      io.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.35 });
  blocks.forEach(function (b) { io.observe(b); });
}

