js:
var sc = root.querySelector('.scr-aperture-plates-sc');
var plates = Array.prototype.slice.call(root.querySelectorAll('.scr-aperture-plates-plate'));

if (!('IntersectionObserver' in window)) {
  plates.forEach(function (p) { p.classList.add('scr-aperture-plates-in'); });
} else {
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (!e.isIntersecting) return;
      var idx = plates.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        plates[k].classList.add('scr-aperture-plates-in');
        io.unobserve(plates[k]);
      }
      e.target.classList.add('scr-aperture-plates-in');
      io.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.32, rootMargin: '0px 0px -8% 0px' });
  plates.forEach(function (p) { io.observe(p); });
}

plates.forEach(function (p) {
  var art = p.querySelector('.scr-aperture-plates-art');
  art.addEventListener('click', function () {
    art.setAttribute('aria-pressed', art.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
  });
});

