js:
var sc = root.querySelector('.scr-rank-cascade-sc');
var list = root.querySelector('.scr-rank-cascade-list');
var rows = Array.prototype.slice.call(root.querySelectorAll('.scr-rank-cascade-row'));
var swts = Array.prototype.slice.call(root.querySelectorAll('.scr-rank-cascade-sw'));
var key = 'w';
var io = null;

function fmt(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function pad(n){ return (n < 10 ? '0' : '') + n; }
function show(el, d){
  el.style.setProperty('--scr-rank-cascade-rd', d + 'ms');
  el.classList.add('scr-rank-cascade-in');
}

function apply(){
  rows.sort(function (a, b) {
    return Number(b.getAttribute('data-' + key)) - Number(a.getAttribute('data-' + key));
  });
  var top = Number(rows[0].getAttribute('data-' + key)) || 1;
  rows.forEach(function (r, i) {
    var v = Number(r.getAttribute('data-' + key));
    list.appendChild(r);
    r.querySelector('.scr-rank-cascade-rk').textContent = pad(i + 1);
    r.querySelector('.scr-rank-cascade-vl').textContent = fmt(v);
    r.style.setProperty('--scr-rank-cascade-v', String(Math.max(6, Math.round(v / top * 100))));
  });
}

function replay(){
  rows.forEach(function (r) {
    r.classList.remove('scr-rank-cascade-in');
    r.style.setProperty('--scr-rank-cascade-rd', '0ms');
  });
  void list.offsetWidth;
  if (io) { rows.forEach(function (r) { io.unobserve(r); io.observe(r); }); }
  else { rows.forEach(function (r) { show(r, 0); }); }
}

if ('IntersectionObserver' in window) {
  io = new IntersectionObserver(function (entries) {
    var batch = entries.filter(function (e) { return e.isIntersecting; });
    batch.sort(function (a, b) { return a.target.offsetTop - b.target.offsetTop; });
    batch.forEach(function (e, i) {
      var idx = rows.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        if (!rows[k].classList.contains('scr-rank-cascade-in')) {
          show(rows[k], 0);
          io.unobserve(rows[k]);
        }
      }
      show(e.target, i * 80);
      io.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.5 });
}

apply();
if (io) { rows.forEach(function (r) { io.observe(r); }); }
else { rows.forEach(function (r) { show(r, 0); }); }

swts.forEach(function (btn) {
  btn.addEventListener('click', function () {
    if (btn.getAttribute('aria-pressed') === 'true') return;
    swts.forEach(function (b) { b.setAttribute('aria-pressed', b === btn ? 'true' : 'false'); });
    key = btn.getAttribute('data-k');
    sc.scrollTop = 0;
    apply();
    replay();
  });
});

