js:
var sc = root.querySelector('.scr-hinge-integrations-sc');
var cards = Array.prototype.slice.call(root.querySelectorAll('.scr-hinge-integrations-card'));
var count = root.querySelector('.scr-hinge-integrations-ct');

function tally(){
  var n = root.querySelectorAll('.scr-hinge-integrations-tg[aria-pressed="true"]').length;
  count.textContent = n + ' connected';
}
function show(el, d){
  el.style.setProperty('--scr-hinge-integrations-cd', d + 'ms');
  el.classList.add('scr-hinge-integrations-in');
}

if (!('IntersectionObserver' in window)) {
  cards.forEach(function (c) { show(c, 0); });
} else {
  var io = new IntersectionObserver(function (entries) {
    var batch = entries.filter(function (e) { return e.isIntersecting; });
    batch.sort(function (a, b) {
      return (a.target.offsetTop - b.target.offsetTop) || (a.target.offsetLeft - b.target.offsetLeft);
    });
    batch.forEach(function (e, i) {
      var idx = cards.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        if (!cards[k].classList.contains('scr-hinge-integrations-in')) {
          show(cards[k], 0);
          io.unobserve(cards[k]);
        }
      }
      show(e.target, i * 75);
      io.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.35 });
  cards.forEach(function (c) { io.observe(c); });
}

cards.forEach(function (c) {
  var btn = c.querySelector('.scr-hinge-integrations-tg');
  btn.addEventListener('click', function () {
    var on = btn.getAttribute('aria-pressed') !== 'true';
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    btn.querySelector('span').textContent = on ? 'Connected' : 'Connect';
    tally();
  });
});
tally();

