var sc = root.querySelector('.scr-pop-testimonials-sc');
var cards = Array.prototype.slice.call(root.querySelectorAll('.scr-pop-testimonials-cd'));

function show(el, d){
  el.style.setProperty('--scr-pop-testimonials-pd', d + 'ms');
  el.classList.add('scr-pop-testimonials-in');
}

if (!('IntersectionObserver' in window)) {
  cards.forEach(function (c) { show(c, 0); });
} else {
  var io = new IntersectionObserver(function (entries) {
    var batch = entries.filter(function (e) { return e.isIntersecting; });
    batch.sort(function (a, b) { return a.target.offsetTop - b.target.offsetTop; });
    batch.forEach(function (e, i) {
      var idx = cards.indexOf(e.target);
      for (var k = 0; k < idx; k++) {
        if (!cards[k].classList.contains('scr-pop-testimonials-in')) {
          show(cards[k], 0);
          io.unobserve(cards[k]);
        }
      }
      show(e.target, i * 110);
      io.unobserve(e.target);
    });
  }, { root: sc, threshold: 0.3, rootMargin: '0px 0px -6% 0px' });
  cards.forEach(function (c) { io.observe(c); });
}

cards.forEach(function (c) {
  var btn = c.querySelector('.scr-pop-testimonials-hf');
  var num = btn.querySelector('b');
  var base = parseInt(num.textContent, 10) || 0;
  btn.addEventListener('click', function () {
    var on = btn.getAttribute('aria-pressed') !== 'true';
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    num.textContent = String(base + (on ? 1 : 0));
  });
});
